body.script:
    // ---------- ХРАНИЛИЩЕ (localStorage) ----------
    const STORAGE = {
        users: 'ars_users',
        articles: 'ars_articles',
        comments: 'ars_comments',
        currentUser: 'ars_current_user'
    };

    function getUsers() { return JSON.parse(localStorage.getItem(STORAGE.users)) || []; }
    function getArticles() { return JSON.parse(localStorage.getItem(STORAGE.articles)) || []; }
    function getComments() { return JSON.parse(localStorage.getItem(STORAGE.comments)) || []; }
    function saveUsers(data) { localStorage.setItem(STORAGE.users, JSON.stringify(data)); }
    function saveArticles(data) { localStorage.setItem(STORAGE.articles, JSON.stringify(data)); }
    function saveComments(data) { localStorage.setItem(STORAGE.comments, JSON.stringify(data)); }

    let currentUser = null;
    let currentView = 'welcome';     // welcome, categoryList, singleArticle, newArticle, myArticles
    let activeCategory = null;
    let activeArticleId = null;

    // инициализация демо-данных
    function seedDatabase() {
        if (!localStorage.getItem(STORAGE.users)) {
            const demoUsers = [
                { id: 1, username: 'critic_vasily', password: '123' },
                { id: 2, username: 'reader_anna', password: '123' }
            ];
            saveUsers(demoUsers);
        }
        if (!localStorage.getItem(STORAGE.articles)) {
            const demoArticles = [
                { id: 101, title: 'Новая волна театральной режиссуры', content: 'Размышления о постдраматическом театре и новых формах...', category: 'teatr', authorId: 1, authorName: 'critic_vasily', createdAt: new Date().toISOString() },
                { id: 102, title: 'Тишина в “Дюне”: звуковой минимализм Вильнёва', content: 'Лоскутный звуковой дизайн погружает зрителя в атмосферу Арракиса...', category: 'kino', authorId: 1, authorName: 'critic_vasily', createdAt: new Date(Date.now() - 86400000).toISOString() },
                { id: 103, title: 'Проза Улицкой: внутри быта и метафизики', content: 'Анализ позднего творчества, этика и семейные хроники.', category: 'literatura', authorId: 1, authorName: 'critic_vasily', createdAt: new Date(Date.now() - 172800000).toISOString() }
            ];
            saveArticles(demoArticles);
        }
        if (!localStorage.getItem(STORAGE.comments)) {
            saveComments([]);
        }
        const storedUser = localStorage.getItem(STORAGE.currentUser);
        if (storedUser) currentUser = JSON.parse(storedUser);
    }

    function saveCurrentUser(u) {
        if (u) localStorage.setItem(STORAGE.currentUser, JSON.stringify(u));
        else localStorage.removeItem(STORAGE.currentUser);
        currentUser = u;
    }
    function genId() { return Date.now() + Math.floor(Math.random() * 10000); }
    function escapeHtml(str) { if(!str) return ''; return str.replace(/[&<>]/g, function(m){ if(m==='&') return '&'; if(m==='<') return '<'; if(m==='>') return '>'; return m;}); }

    function getCatName(cat) { if(cat==='teatr') return 'Театр'; if(cat==='kino') return 'Кино'; return 'Литература'; }

    // ---------- ОТРИСОВКА ПРАВОГО САЙДБАРА ----------
    function renderRightSidebar() {
        const articles = getArticles().sort((a,b)=> new Date(b.createdAt) - new Date(a.createdAt)).slice(0,5);
        const container = document.getElementById('rightSidebarList');
        if (!container) return;
        if (articles.length === 0) { container.innerHTML = '
Скоро появятся статьи'; return; }
        container.innerHTML = articles.map(art => `



${escapeHtml(art.title)}

${escapeHtml(art.authorName)} · ${new Date(art.createdAt).toLocaleDateString()}

        `).join('');
        document.querySelectorAll('.sidebar-article').forEach(el => {
            el.addEventListener('click', (e) => {
                const id = parseInt(el.getAttribute('data-id'));
                showArticleDetail(id);
            });
        });
    }

    // ---------- ОТРИСОВКА ЦЕНТРАЛЬНОЙ ЗОНЫ ----------
    function renderWelcomePage() {
        // Полный текст по требованию — газетная вёрстка с блоками "Авторам", "Читателям", "Как начать"
        return `



Ars longa, vita brevis

Искусство вечно, жизнь коротка.

Мы живём в эпоху трёхсекундных видео и бесконечных лент.
Эта платформа — пространство, где искусство говорит текстом.


Ars Longa — независимая отечественная платформа для глубокого разговора об искусстве. Мы объединяем три направления — кино, театр и литературу — в едином пространстве, где можно не скроллить, а читать. Не пролистывать, а осмыслять.

Здесь собираются авторы, которые хотят быть услышанными, и читатели, которые устали от информационного шума. Мы не социальная сеть. Мы не «витрина» и не архив для избранных. Ars Longa — это точка входа в культурный дискурс для всех, кому есть что сказать и кто хочет слушать.





Авторам

Вы пишете рецензии, критические статьи, эссе о кино, театре или литературе.
Вы хотите, чтобы ваши тексты читали, обсуждали и цитировали.

Ars Longa даёт вам:


Готовую аудиторию — люди приходят сюда специально за глубоким контентом. Вам не нужно вести блог, раскручивать Telegram-канал или снимать Reels, чтобы быть замеченным.

Портфолио и имя — каждая ваша публикация становится частью вашего профессионального профиля. Редакторы, кураторы, галеристы видят ваши работы.

Обратную связь — оценки, комментарии, рейтинг автора. Вы растёте вместе с сообществом.

Свободу от алгоритмов — ваш текст не тонет в ленте среди разрозненного контента и рекламы. Он живёт в нишевом пространстве и находится через поиск спустя месяцы.

Фокус на тексте — удобный редактор, никакого давления в сторону короткого контента. Вы просто пишете.


Неважно, студент вы или состоявшийся критик.
Здесь ценится мысль, а не имя.






Читателям

Вы любите искусство и хотите понимать его глубже.
Вам надоело натыкаться на поверхностные посты и эмоциональные выплески без аргументов.

Ars Longa даёт вам:


Качественный контент — рецензии, разборы, аналитические статьи, эссе. Всё проходит модерацию, которая отсеивает графоманию и откровенный спам.

Междисциплинарный охват — кино, театр и литература на одной площадке. Вы можете исследовать связи между видами искусства, не переключаясь между разными сайтами.

Удобный поиск — по авторам, тегам, категориям, ключевым словам. Нужен разбор «Гамлета»? Вы найдёте его в несколько кликов.

Доверие — вы знаете, что автор прошёл проверку платформы, а его текст — часть осмысленного культурного диалога.

Дискуссию — вы можете спорить, дополнять и обсуждать каждую публикацию в комментариях.


Это место, куда приходят за пониманием, а не за развлечением.






Как начать

Читать можно сразу. Выбирайте раздел — Театр, Кино или Литература — и погружайтесь.

Писать — три шага:


Зарегистрируйтесь — создайте учётную запись. Это быстро и бесплатно.

Напишите статью — в удобном редакторе подготовьте черновик рецензии, эссе или аналитического разбора.

Отправьте на модерацию — ваш текст проверят на соответствие формату и качеству. После одобрения он появится на платформе и станет доступен всем читателям.


Никаких сложных порогов входа. Только вы, текст и аудитория, которая ждёт.



Ars longa. Пишите вечное.
        `;
    }

    function renderCenter() {
        const centerDiv = document.getElementById('dynamicCenter');
        if (!centerDiv) return;
        if (currentView === 'welcome') {
            centerDiv.innerHTML = renderWelcomePage();
            attachDropcap();
        } else if (currentView === 'categoryList' && activeCategory) {
            const articles = getArticles().filter(a => a.category === activeCategory).sort((a,b)=> new Date(b.createdAt)-new Date(a.createdAt));
            centerDiv.innerHTML = `
${getCatName(activeCategory)}

${articles.map( art => `



${escapeHtml(art.title)}

${escapeHtml(art.authorName)} · ${new Date(art.createdAt).toLocaleDateString()}

${escapeHtml(art.content.substring(0,120))}…

            `).join('')}`;
            if(articles.length===0) centerDiv.innerHTML += `
Пока нет статей в этом разделе. Станьте первым автором!`;
            attachArticleCardListeners();
        } else if (currentView === 'singleArticle' && activeArticleId) {
            renderSingleArticle(centerDiv);
        } else if (currentView === 'newArticle') {
            if(!currentUser) { showAuthModal(); return; }
            centerDiv.innerHTML = `


Новая статья
                Заголовок
                КатегорияТеатрКиноЛитература
                Содержание
                Опубликовать Отмена

`;
            document.getElementById('publishArtBtn')?.addEventListener('click', () => {
                const title = document.getElementById('artTitle').value.trim();
                const content = document.getElementById('artContent').value.trim();
                const cat = document.getElementById('artCat').value;
                if(!title || !content) { document.getElementById('artError').innerText = 'Заполните поля'; return; }
                const newArticle = { id: genId(), title, content, category: cat, authorId: currentUser.id, authorName: currentUser.username, createdAt: new Date().toISOString() };
                const articles = getArticles();
                articles.push(newArticle);
                saveArticles(articles);
                currentView = 'welcome';
                renderCenter();
                renderRightSidebar();
            });
            document.getElementById('cancelNewArt')?.addEventListener('click', ()=>{ currentView='welcome'; renderCenter(); });
        } else if (currentView === 'myArticles') {
            if(!currentUser) { showAuthModal(); return; }
            const myArts = getArticles().filter(a => a.authorId === currentUser.id);
            centerDiv.innerHTML = `
Мои статьи
${myArts.map(art => `



${escapeHtml(art.title)}

${getCatName(art.category)} · ${new Date(art.createdAt).toLocaleDateString()}
                    Удалить

            `).join('')}`;
            document.querySelectorAll('.deleteMyArticleBtn').forEach(btn => {
                btn.addEventListener('click', (e) => {
                    e.stopPropagation();
                    const id = parseInt(btn.getAttribute('data-id'));
                    if(confirm('Удалить статью?')){
                        let newArts = getArticles().filter(a=>a.id !== id);
                        saveArticles(newArts);
                        let newCom = getComments().filter(c=>c.articleId !== id);
                        saveComments(newCom);
                        renderCenter();
                        renderRightSidebar();
                    }
                });
            });
            attachArticleCardListeners();
        }
        if(currentView !== 'singleArticle') attachCategoryAndSidebarTriggers();
        renderAuthButton();
    }

    function renderSingleArticle(container) {
        const article = getArticles().find(a => a.id === activeArticleId);
        if (!article) { container.innerHTML = '
Статья не найдена'; return; }
        const comments = getComments().filter(c => c.articleId === activeArticleId).sort((a,b)=> new Date(b.createdAt)-new Date(a.createdAt));
        const isAuthor = currentUser && currentUser.id === article.authorId;
        container.innerHTML = `



${escapeHtml(article.title)}

${escapeHtml(article.authorName)} · ${getCatName(article.category)} · ${new Date(article.createdAt).toLocaleDateString()}

${escapeHtml(article.content)}
                ${isAuthor ? `Удалить статью` : ''}


Комментарии

                ${currentUser ? `Отправить` : `
Войдите, чтобы комментировать`}


            `;
        const commentContainer = document.getElementById('commentList');
        function renderCommentsList() {
            const freshComments = getComments().filter(c => c.articleId === activeArticleId);
            commentContainer.innerHTML = freshComments.map(c => `


${escapeHtml(c.userName)} ${new Date(c.createdAt).toLocaleString()}

${escapeHtml(c.text)}
                ${ (currentUser && (currentUser.id === c.userId || currentUser.id === article.authorId)) ? `Удалить` : ''}
                `).join('');
            document.querySelectorAll('.deleteCommentBtn').forEach(btn => {
                btn.addEventListener('click', (e) => {
                    const commId = parseInt(btn.getAttribute('data-id'));
                    const newComms = getComments().filter(cc=>cc.id !== commId);
                    saveComments(newComms);
                    renderCommentsList();
                });
            });
        }
        renderCommentsList();
        document.getElementById('submitCommentBtn')?.addEventListener('click', () => {
            const text = document.getElementById('newCommentText').value;
            if(!text.trim()) return;
            const newComm = { id: genId(), articleId: activeArticleId, userId: currentUser.id, userName: currentUser.username, text: text.trim(), createdAt: new Date().toISOString() };
            const all = getComments();
            all.push(newComm);
            saveComments(all);
            document.getElementById('newCommentText').value = '';
            renderCommentsList();
        });
        document.getElementById('deleteArticleBtn')?.addEventListener('click', () => {
            if(confirm('Удалить?')) {
                saveArticles(getArticles().filter(a=>a.id !== activeArticleId));
                saveComments(getComments().filter(c=>c.articleId !== activeArticleId));
                currentView = 'welcome';
                renderCenter();
                renderRightSidebar();
            }
        });
        document.getElementById('loginToCommentBtn')?.addEventListener('click', () => showAuthModal());
    }

    function attachArticleCardListeners() {
        document.querySelectorAll('.article-mini-card').forEach(card => {
            const idAttr = card.getAttribute('data-id');
            if(idAttr) card.addEventListener('click', (e) => { if(!e.target.classList.contains('deleteMyArticleBtn')) showArticleDetail(parseInt(idAttr)); });
        });
    }
    function showArticleDetail(id) { activeArticleId = id; currentView = 'singleArticle'; renderCenter(); renderRightSidebar(); }
    function attachDropcap() { const dropElem = document.querySelector('.dropcap'); if(dropElem) dropElem.classList.add('dropcap'); }
    function attachCategoryAndSidebarTriggers() {
        document.querySelectorAll('.category-btn').forEach(btn => {
            btn.removeEventListener('click', categoryHandler);
            btn.addEventListener('click', categoryHandler);
        });
    }
    function categoryHandler(e) { activeCategory = e.currentTarget.getAttribute('data-cat'); currentView = 'categoryList'; renderCenter(); renderRightSidebar(); }

    function showAuthModal() {
        const modalDiv = document.createElement('div'); modalDiv.className = 'modal';
        modalDiv.innerHTML = `

Вход / РегистрацияВойтиЗарегистрироваться
Закрыть`;
        document.body.appendChild(modalDiv);
        modalDiv.querySelector('#doLogin').onclick = () => {
            const users = getUsers();
            const u = users.find(us => us.username === modalDiv.querySelector('#authUsername').value && us.password === modalDiv.querySelector('#authPassword').value);
            if(u) { saveCurrentUser({id: u.id, username: u.username}); modalDiv.remove(); renderCenter(); renderRightSidebar(); renderAuthButton(); }
            else modalDiv.querySelector('#authMsg').innerText = 'Ошибка входа';
        };
        modalDiv.querySelector('#doRegister').onclick = () => {
            const users = getUsers();
            const name = modalDiv.querySelector('#authUsername').value, pass = modalDiv.querySelector('#authPassword').value;
            if(!name || !pass) { modalDiv.querySelector('#authMsg').innerText = 'Заполните поля'; return; }
            if(users.find(u=>u.username===name)) { modalDiv.querySelector('#authMsg').innerText = 'Имя занято'; return; }
            const newId = genId();
            users.push({ id: newId, username: name, password: pass });
            saveUsers(users);
            saveCurrentUser({id: newId, username: name});
            modalDiv.remove(); renderCenter(); renderRightSidebar(); renderAuthButton();
        };
        modalDiv.querySelector('#closeModal').onclick = () => modalDiv.remove();
    }

    function renderAuthButton() {
        const btn = document.getElementById('authBtnSticky');
        if(!btn) return;
        if(currentUser) btn.innerHTML = `⊙ ${currentUser.username}`;
        else btn.innerHTML = `⊙ Аккаунт`;
        if(currentUser) {
            if(!document.getElementById('myArticlesBtnSticky')) {
                const parent = document.querySelector('.header-actions-bottom');
                const myArtBtn = document.createElement('button'); myArtBtn.id = 'myArticlesBtnSticky'; myArtBtn.className = 'icon-btn'; myArtBtn.innerHTML = '📄 Мои статьи';
                myArtBtn.onclick = () => { currentView = 'myArticles'; renderCenter(); };
                parent?.insertBefore(myArtBtn, document.getElementById('menuBtnSticky'));
                const newBtn = document.createElement('button'); newBtn.id = 'newPostBtnSticky'; newBtn.className = 'icon-btn'; newBtn.innerHTML = '✎ Написать';
                newBtn.onclick = () => { currentView = 'newArticle'; renderCenter(); };
                parent?.insertBefore(newBtn, document.getElementById('menuBtnSticky'));
            }
        } else {
            document.getElementById('myArticlesBtnSticky')?.remove();
            document.getElementById('newPostBtnSticky')?.remove();
        }
    }

    function initUI() {
        seedDatabase();
        renderRightSidebar();
        renderCenter();
        document.getElementById('searchBtnSticky')?.addEventListener('click', () => { const q = prompt('Поиск статей:'); if(q) { const arts = getArticles().filter(a=>a.title.toLowerCase().includes(q.toLowerCase())); const center = document.getElementById('dynamicCenter'); if(arts.length) center.innerHTML = `
${arts.map(a=>`

${escapeHtml(a.title)}
${escapeHtml(a.content.substring(0,100))}`).join('')}`; else center.innerHTML='
Ничего не найдено'; attachArticleCardListeners(); } });
        document.getElementById('authBtnSticky')?.addEventListener('click', showAuthModal);
        document.getElementById('menuBtnSticky')?.addEventListener('click', () => alert('Фильтры и настройки (демо): сортировка, избранное — в разработке'));
        document.getElementById('guideFirstArticle')?.addEventListener('click', ()=> alert('Совет: пишите о том, что вас действительно волнует. Живой язык и личный взгляд — главное.'));
        document.getElementById('guideRules')?.addEventListener('click', ()=> alert('Уникальность, объём от 1500 знаков, аргументированность. Модерация отсеивает спам.'));
        document.getElementById('guideTips')?.addEventListener('click', ()=> alert('Читайте других авторов, комментируйте. Сообщество ценит диалог.'));
        window.addEventListener('scroll', () => {
            const topBar = document.querySelector('.top-bar');
            if(window.scrollY > 60) topBar?.classList.add('hidden-logo');
            else topBar?.classList.remove('hidden-logo');
        });
    }
    window.addEventListener('DOMContentLoaded', initUI);
